sys_script_include.script:
var HelpDeskAndFeedbackRefQual = Class.create();
HelpDeskAndFeedbackRefQual.prototype = {

    initialize: function() {
    },

    getLoggedInCollege: function() {

        var emp = new GlideRecord('x_1790229_edusph_0_employee');
        emp.addQuery('user', gs.getUserID());
        emp.addQuery('active', true);
        emp.setLimit(1);
        emp.query();

        if (emp.next()) {

            var collegeId = emp.getValue('college');

            var college = new GlideRecord('x_1790229_edusph_0_college');
            college.addQuery('sys_id', collegeId);
            college.addQuery('status', 'active');
            college.setLimit(1);
            college.query();

            if (college.next()) {
                return 'sys_idIN' + collegeId;
            }
        }

        return 'sys_idINempty';
    },

    getLoggedInRequester: function() {

        var userId = gs.getUserID();

        if (!userId) {
            return 'sys_idINempty';
        }

        return 'sys_idIN' + userId;
    },


// Form: Active forms belonging to logged-in College
getActiveFormByCollege: function() {

    var collegeId = this.getLoggedInCollege();

    if (!collegeId) return 'sys_idINempty';

    var form = new GlideRecord('x_1790229_edusph_0_feedback_form');
    form.addQuery('active', true);

    var condition = form.addQuery('semester.college', collegeId);
    condition.addOrCondition('event.college', collegeId);

    form.query();

    var ids = [];

    while (form.next()) {
        ids.push(form.getUniqueValue());
    }

    return ids.length ? 'sys_idIN' + ids.join(',') : 'sys_idINempty';
},

// Semester: Semester of logged-in Student
getSemesterByLoggedInUser: function() {

    var student = new GlideRecord('x_1790229_edusph_0_student');
    student.addQuery('user', gs.getUserID());
    student.setLimit(1);
    student.query();

    if (student.next() && student.getValue('semester')) {
        return 'sys_idIN' + student.getValue('semester');
    }

    return 'sys_idINempty';
},

// Course Offering: College + Semester + Section of logged-in Student
getOfferingByLoggedInUser: function() {

    var student = new GlideRecord('x_1790229_edusph_0_student');
    student.addQuery('user', gs.getUserID());
    student.setLimit(1);
    student.query();

    if (!student.next()) return 'sys_idINempty';

    var college = student.getValue('college');
    var semester = student.getValue('semester');
    var section = student.getValue('section');

    if (!college || !semester || !section) {
        return 'sys_idINempty';
    }

    var offering = new GlideRecord('x_1790229_edusph_0_course_offering');
    offering.addQuery('college', college);
    offering.addQuery('semester', semester);
    offering.addQuery('section', section);
    offering.query();

    var ids = [];

    while (offering.next()) {
        ids.push(offering.getUniqueValue());
    }

    return ids.length ? 'sys_idIN' + ids.join(',') : 'sys_idINempty';
},

// Student: Logged-in Student only
getLoggedInStudent: function() {

    var student = new GlideRecord('x_1790229_edusph_0_student');
    student.addQuery('user', gs.getUserID());
    student.setLimit(1);
    student.query();

    if (student.next()) {
        return 'sys_idIN' + student.getUniqueValue();
    }

    return 'sys_idINempty';
},

// Employee: Active Employees belonging to logged-in College
getEmployeeByCollege: function() {

    var collegeId = this.getLoggedInCollege();

    if (!collegeId) return 'sys_idINempty';

    var emp = new GlideRecord('x_1790229_edusph_0_employee');
    emp.addQuery('college', collegeId);
    emp.addQuery('active', true);
    emp.query();

    var ids = [];

    while (emp.next()) {
        ids.push(emp.getUniqueValue());
    }

    return ids.length ? 'sys_idIN' + ids.join(',') : 'sys_idINempty';
},

// Event: Events belonging to logged-in College
getEventByCollege: function() {

    var collegeId = this.getLoggedInCollege();

    if (!collegeId) return 'sys_idINempty';

    var event = new GlideRecord('x_1790229_edusph_0_event');
    event.addQuery('college', collegeId);
    event.query();

    var ids = [];

    while (event.next()) {
        ids.push(event.getUniqueValue());
    }

    return ids.length ? 'sys_idIN' + ids.join(',') : 'sys_idINempty';
},
    type: 'HelpDeskAndFeedbackRefQual'
};
